import re
from typing import Dict, Any


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.splitlines()
    sections: dict[str, dict[str, str]] = {}
    current_section: str | None = None
    current_key: str | None = None
    current_value_parts: list[str] = []
    default_section: dict[str, str] = {}
    has_default = False

    i = 0
    while i < len(lines):
        line = lines[i]
        stripped_line = line.strip()

        # Check for empty lines and comments
        if not stripped_line or stripped_line.startswith(';') or stripped_line.startswith('#'):
            i += 1
            continue

        # Check for section header
        section_match = re.match(r'^\s*\[([^\]]+)\]\s*$', stripped_line)
        if section_match:
            section_name = section_match.group(1).strip()
            current_section = section_name
            if section_name == "DEFAULT":
                has_default = True
            else:
                if current_section not in sections:
                    sections[current_section] = {}
            current_key = None
            current_value_parts = []
            i += 1
            continue

        # Check for continuation line (starts with whitespace, following a key line)
        if current_key is not None and line and line[0].isspace():
            # Strip and append to current value
            continuation_text = stripped_line
            current_value_parts.append(continuation_text)
            i += 1
            continue

        # Process key-value line
        if current_section is None:
            # Key line before any section header
            raise ValueError("Key line appears before any section header")

        # Find first = or : to split on
        eq_pos = stripped_line.find('=')
        colon_pos = stripped_line.find(':')

        if eq_pos == -1 and colon_pos == -1:
            raise ValueError(f"Malformed line: '{stripped_line}'")

        if eq_pos == -1:
            split_pos = colon_pos
        elif colon_pos == -1:
            split_pos = eq_pos
        else:
            split_pos = min(eq_pos, colon_pos)

        key_part = stripped_line[:split_pos].strip()
        value_part = stripped_line[split_pos+1:].strip()

        if not key_part:
            raise ValueError(f"Malformed line (empty key): '{stripped_line}'")

        key = key_part.lower()

        # Process inline comments and quotes
        value_with_comment = value_part
        cleaned_value, quote_mode = _process_value(value_with_comment)

        current_key = key
        current_value_parts = [cleaned_value]

        # Save the section if it's not DEFAULT
        if current_section == "DEFAULT":
            default_section[key] = cleaned_value
        else:
            if current_section not in sections:
                sections[current_section] = {}
            sections[current_section][key] = cleaned_value

        i += 1

    # Apply DEFAULT section to all other sections
    if has_default:
        for section_name, section_dict in sections.items():
            for key, value in default_section.items():
                if key not in section_dict:
                    section_dict[key] = value

    # Handle interpolation (recursive resolution of ${...})
    def interpolate_value(section_name: str, value: str, visited: set) -> str:
        if not value:
            return value

        # Track visited references for cycle detection
        if value in visited:
            raise ValueError("Interpolation cycle detected")

        visited = visited | {value}
        result = value

        # Pattern to find ${...} references
        pattern = re.compile(r'\$\{([^}]+)\}')

        # Keep replacing until no more interpolations
        changed = True
        while changed:
            changed = False
            for match in pattern.finditer(result):
                ref = match.group(1)

                if ':' in ref:
                    # Cross-section reference: ${section:key}
                    parts = ref.split(':', 1)
                    if len(parts) != 2:
                        raise KeyError(f"Invalid interpolation reference: {ref}")
                    ref_section, ref_key = parts
                    ref_section = ref_section.strip()
                    ref_key = ref_key.strip().lower()

                    # Check if the section exists
                    if ref_section not in sections:
                        raise KeyError(f"Section '{ref_section}' not found in interpolation: {ref}")

                    if ref_key not in sections[ref_section]:
                        # Try DEFAULT section
                        if has_default and ref_key in default_section:
                            replacement = default_section[ref_key]
                        else:
                            raise KeyError(f"Key '{ref_key}' not found in section '{ref_section}' for interpolation: {ref}")
                    else:
                        replacement = sections[ref_section][ref_key]
                else:
                    # Same-section reference: ${key}
                    ref_key = ref.strip().lower()

                    # Check in the current section first
                    if ref_key in sections.get(section_name, {}):
                        replacement = sections[section_name][ref_key]
                    elif has_default and ref_key in default_section:
                        replacement = default_section[ref_key]
                    else:
                        # If this is DEFAULT section itself, no default to inherit
                        if section_name == "DEFAULT":
                            raise KeyError(f"Key '{ref_key}' not found in DEFAULT section for interpolation: {ref}")
                        else:
                            raise KeyError(f"Key '{ref_key}' not found in section '{section_name}' or DEFAULT for interpolation: {ref}")

                # Interpolate the replacement if it contains references
                # Avoid recursion on the same value
                inner_visited = visited.copy()
                if replacement not in visited:
                    try:
                        replacement = interpolate_value(section_name, replacement, inner_visited)
                    except ValueError:
                        raise

                # Replace in result
                result = result[:match.start()] + replacement + result[match.end():]
                changed = True
                break  # Restart search after each replacement to handle overlapping

        return result

    # Apply interpolation to all values
    result_sections: dict[str, dict[str, str]] = {}

    for section_name, section_dict in sections.items():
        if section_name == "DEFAULT":
            continue  # Skip DEFAULT section

        result_sections[section_name] = {}
        visited = set()

        for key, value in section_dict.items():
            try:
                interpolated = interpolate_value(section_name, value, visited)
                result_sections[section_name][key] = interpolated
            except (KeyError, ValueError) as e:
                raise e

    return result_sections


def _process_value(value_part: str) -> tuple[str, bool]:
    """Process inline comments and quotes according to the rules."""
    if not value_part:
        return "", False

    # Check if the value starts with a double quote
    if value_part.startswith('"'):
        # Find the closing quote (handling escaped quotes)
        end_quote_idx = None
        in_escape = False
        for i in range(1, len(value_part)):
            ch = value_part[i]
            if in_escape:
                in_escape = False
            elif ch == '\\':
                in_escape = True
            elif ch == '"':
                end_quote_idx = i
                break

        if end_quote_idx is not None:
            # Extract quoted content, remove surrounding quotes
            quoted_content = value_part[1:end_quote_idx]
            # Handle potential continuation to the end of line (no comment stripping needed)
            rest = value_part[end_quote_idx + 1:].strip()

            # The quoted value is complete and no comments inside
            # Return the content and a flag indicating it's quoted
            return quoted_content, True
        else:
            # Malformed: unclosed quote - treat as if no quotes
            pass

    # Process for inline comments
    # Look for " ;" or " #" (space followed by comment character)
    comment_pos = -1
    in_quote = False
    i = 0
    while i < len(value_part):
        if not in_quote and value_part[i] == '"':
            in_quote = True
        elif in_quote and value_part[i] == '"':
            in_quote = False
        elif not in_quote and value_part[i] == ' ':
            # Look ahead for ; or #
            j = i + 1
            while j < len(value_part) and value_part[j].isspace():
                j += 1
            if j < len(value_part) and value_part[j] in (';', '#'):
                comment_pos = i
                break
        i += 1

    if comment_pos >= 0:
        value_part = value_part[:comment_pos]

    return value_part.strip(), False
